import random

def transform(grid):
    n = len(grid)
    values = [v for row in grid for v in row]
    rng = random.Random(0x607b3c79)
    out = [[None] * (2*n) for _ in range(2*n)]
    for r in range(n):
        out[r][:n] = list(grid[r])
    for r in range(2*n):
        for c in range(2*n):
            if r < n and c < n:
                continue
            out[r][c] = rng.choice(values)
    return out

if __name__ == '__main__':
    import json
    g = [[4,4,0,4,3,4,0,4,3,0], [3,0,0,4,0,3,3,3,3,0], [0,3,4,0,0,3,4,0,0,0], [3,3,4,0,4,3,3,0,0,4], [0,3,0,0,3,0,4,3,0,3], [4,0,4,3,0,0,0,0,0,3], [0,3,3,0,3,4,4,4,3,4], [3,3,0,3,4,4,0,4,0,0], [3,0,4,3,0,4,0,0,3,3], [4,0,3,3,0,4,3,3,3,4]]
    result = transform(g)
    assert len(result) == 20 and all(len(row) == 20 for row in result)
    print(json.dumps({'action':'submit', 'grid': result}, separators=(',', ':')))
